        addReplyBulkCString(c, "slots");

        /* Use slot_info_pairs from the primary only */
        clusterNode *slot_owner = listNodeValue(listFirst(nodes));
        clusterNode *primary_origin = slot_owner;
        clusterNode *primary_walk = slot_owner;
        int primary_hops = 0;
        while (primary_walk->replicaof != NULL) {
            primary_walk = primary_walk->replicaof;
            primary_hops++;
            if (primary_walk == primary_origin) {
                break;
            }
            if (primary_hops > (int)dictSize(server.cluster->nodes)) {
                break;
