        int owner_pair_count = slot_owner->slot_info_pairs_count;
        if (owner_pairs != NULL) {
            serverAssert((owner_pair_count % 2) == 0);
            addReplyArrayLen(c, owner_pair_count);
            for (int pair_idx = 0; pair_idx < owner_pair_count; pair_idx++) {
                unsigned long slot_bound = (unsigned long)owner_pairs[pair_idx];
